INSERT INTO `temples` (`id`, `name`, `name_bn`, `picture`, `address`, `latitude`, `longitude`, `description`, `division_id`, `district_id`, `upazila_id`, `created_by`, `updated_by`, `union_parisad`, `village`, `city_corp`, `ward`, `thana`, `post_office`, `zipcode`, `contact_name`, `contact_no`, `designation`, `nid`, `main_picture`, `status`, `residential_facility`, `created_at`, `updated_at`) VALUES
(1, 'Dhakeshwari National Temple', 'ঢাকেশ্বরী জাতীয় মন্দির', NULL, 'Dhakeshwari Road, Dhaka 1100', '23.7286', '90.3880', '<p>Dhakeshwari Temple (Bengali: ঢাকেশ্বরী মন্দির) is a state-owned Hindu temple in Dhaka, Bangladesh. It is the national temple of Bangladesh. The name \"Dhakeshwari\" means \"Goddess of Dhaka\". Since the destruction of Ramna Kali Mandir in 1971 by the Pakistan Army during the Bangladesh Liberation War, the Dhakeshwari Temple has assumed status as the most important Hindu place of worship in Bangladesh.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; padding: 0px; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: 1.9; font-family: Poppins, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 14px; color: rgb(119, 119, 119);\">The temple\'s history is intertwined with the history of Dhaka itself. It is widely believed that the city was named after the Goddess Dhakeshwari. The main deity is a ten-armed goddess, a form of Durga, which is a significant figure in the Shakta tradition of Hinduism. The temple complex has undergone several renovations and additions over the centuries, reflecting the changing architectural styles and the patronage of various rulers and devotees.</p>', 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5684', NULL, '01636524141', NULL, NULL, '4ef843ca-d16c-4944-b84d-e7ee859a71bc.jpg', 1, 0, '2025-11-28 00:12:47', '2025-11-30 08:43:25'),
(2, 'Ramna Kali Mandir', 'রমনা কালী মন্দির', NULL, 'Ramna, Dhaka 1000', '23.7365', '90.3958', 'Historic temple located in the Ramna area of Dhaka.', 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5f2c39a4-801b-433b-be44-60f846ce3b09.jpg', 1, 0, '2025-11-28 00:12:47', '2025-12-04 13:53:06'),
(3, 'Kalibari Temple Gazipur', 'কালীবাড়ি মন্দির গাজীপুর', NULL, 'Gazipur City, Gazipur', '23.9999', '90.4200', 'Beautiful Kali temple in Gazipur with residential facilities.', 1, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2025-11-28 00:12:47', '2025-11-28 00:12:47'),
(4, 'Sri Sri Lakshmi Narayan Temple', 'শ্রী শ্রী লক্ষ্মী নারায়ণ মন্দির', NULL, 'Lakshmibazar, Dhaka 1100', '23.7104', '90.4074', 'Temple dedicated to Lord Vishnu and Goddess Lakshmi.', 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1117b1bf-ba20-4a3a-b36d-dc60ebe21af6.jpg', 1, 0, '2025-11-28 00:12:47', '2025-12-04 13:58:46'),
(5, 'Shri Shri Loknath Brahmachari Ashram & Mandir', NULL, NULL, 'uttara 102', '23.719', '90.422', '<p>Test</p>', 1, 1, 150, NULL, NULL, NULL, NULL, 'Chittagong', NULL, NULL, NULL, '4000', NULL, NULL, NULL, NULL, 'ad352235-779c-4edf-865e-b166bd93b13d.jpg', 1, 0, '2025-11-28 15:20:21', '2025-12-04 09:36:10'),
(6, 'Sree Sree Chatteshwari Kali Temple', 'শ্রী শ্রী চট্টেশ্বরী কালী মন্দির', NULL, 'Radha Mollick House , Chapra Village', '22.355', '91.826', '<p>tt</p>', 2, 17, NULL, NULL, NULL, NULL, NULL, 'Kalarpole', NULL, NULL, NULL, '4371', NULL, NULL, NULL, NULL, '9782593f-312d-47b5-a37d-0c9ccbff9999.jpg', 1, 0, '2025-11-28 15:25:12', '2025-12-04 13:38:41'),
(11, 'The International Society for Krishna Consciousness', NULL, NULL, 'VVX4+Q3R Sylhet, Bangladesh', '24.8994875', '91.8551406', '<div style=\"font-family: Roboto, Arial, sans-serif; font-size: 13px;\"><h1 class=\"DUwDvf lfPIob\" style=\"background: transparent; border: 0px; border-radius: 0px; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: 1.375rem; line-height: 1.75rem; font-family: &quot;Google Sans&quot;, Roboto, Arial, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; list-style: none; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; overflow: visible; padding: 0px; vertical-align: baseline; letter-spacing: 0rem; color: rgb(31, 31, 31);\">The International Society for Krishna Consciousness<span class=\"G0bp3e\" style=\"align-self: start;\"></span></h1></div><h2 class=\"bwoZTb fontBodyMedium\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border: 0px; border-radius: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 0.875rem; line-height: 1.25rem; font-family: &quot;Google Sans&quot;, Roboto, Arial, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; list-style: none; margin: 4px 0px 0px; outline: 0px; overflow: visible; padding: 0px; vertical-align: baseline; letter-spacing: 0.00625rem; color: rgb(94, 94, 94);\">ইসকন সিলেট</h2>', 8, 52, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a9bd5ac3-c67f-4a5d-a94f-5a722b08a345.jpg', 1, 0, '2025-11-28 16:46:10', '2025-12-04 13:31:07'),
